'use strict'

// Standalone product prototype. It never reads the application store or calls a service.
const themes = [
  { id: 'paper', name: 'Papier', desc: 'Ciepła biel, spokojna zieleń', colors: ['#f3f2eb','#193a37','#294f49','#657a70'] },
  { id: 'ink', name: 'Atrament', desc: 'Ciemny, miękki kontrast', colors: ['#172628','#edf3ed','#abcab7','#9aaea4'] },
  { id: 'obsidian', name: 'Obsydian', desc: 'Czerń i wysoki kontrast', colors: ['#000000','#ffffff','#ffffff','#aaaaaa'] },
  { id: 'sage', name: 'Szałwia', desc: 'Naturalne odcienie zieleni', colors: ['#edf1e7','#273c2b','#415e3b','#6c7b65'] },
  { id: 'eink', name: 'E-ink', desc: 'Monochromatyczny, bez animacji', colors: ['#ffffff','#000000','#000000','#666666'] },
  { id: 'lavender', name: 'Lawenda', desc: 'Jasny fiolet i śliwka', colors: ['#f4f1f8','#362c4d','#6e537d','#7f718e'] },
  { id: 'sand', name: 'Piasek', desc: 'Piaskowe tło, ciepły akcent', colors: ['#f6efe3','#4b3527','#9a502c','#8b725a'] },
]
const state = { theme:'paper', running:false, end:0, remaining:25*60, task:'Plan na nowy tydzień', phase:'focus', deleted:false, language:'pl' }
const app = document.querySelector('#app')
const routes = new Map()
const register = (id,title,group,kind,content,footer,version='3.1') => routes.set(id,{id,title,group,kind,content,footer,version})
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const icon = (name,size=20) => {
  const paths={close:'m6 6 12 12M6 18 18 6',back:'m15 18-6-6 6-6',arrow:'m9 18 6-6-6-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',sound:'m11 5-6 4H2v6h3l6 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',cloud:'M7 18a5 5 0 1 1 0-10 7 7 0 0 1 13 3 3.5 3.5 0 0 1-1 7H7Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',book:'M12 6s-4-3-9-1v15c5-2 9 1 9 1s4-3 9-1V5c-5-2-9 1-9 1Zm0 0v15',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',globe:'M2 12h20M12 2c6 6 6 14 0 20-6-6-6-14 0-20Zm10 10a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',desktop:'M3 4h18v13H3ZM12 17v4m-5 0h10',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 10 3 3 5-6',dots:'M5 12h.01M12 12h.01M19 12h.01',pause:'M8 5v14M16 5v14',play:'m8 5 11 7-11 7V5Z',reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z'}
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.settings}"/></svg>`
}
const nav = (id,label,cls='btn',ico='') => `<a href="#${id}" class="${cls}">${ico?icon(ico):''}${label}</a>`
const action = (id,label,cls='btn',ico='') => `<button type="button" class="${cls}" data-action="${id}">${ico?icon(ico):''}${label}</button>`
const note = (text,error=false) => `<div class="note${error?' error':''}">${text}</div>`
const row = (id,title,desc='',ico='settings') => `<a class="settings-row" href="#${id}"><span class="glyph">${icon(ico)}</span><span class="grow"><strong>${title}</strong>${desc?`<small>${desc}</small>`:''}</span><span class="arrow">${icon('arrow',18)}</span></a>`
const toggle = (label,desc='',on=false) => `<div class="switch-row"><span class="switch-copy"><strong>${label}</strong>${desc?`<small>${desc}</small>`:''}</span><button type="button" class="switch" role="switch" aria-checked="${on}" aria-label="${label}"><span class="switch-track"></span></button></div>`
const field = (label,value,type='text',desc='') => `<label class="field"><span class="field-label">${label}</span><input class="input" type="${type}" value="${esc(value)}">${desc?`<small>${desc}</small>`:''}</label>`
const range = (label,value,min,max,unit='',ends=[]) => `<label class="field"><span class="field-label">${label}<output>${value}${unit}</output></span><input type="range" min="${min}" max="${max}" value="${value}" aria-label="${label}" data-unit="${unit}">${ends.length?`<span class="range-ends"><span>${ends[0]}</span><span>${ends[1]}</span></span>`:''}</label>`
const options = (group,labels,active=0) => `<div class="pill-options" role="group" aria-label="${group}">${labels.map((l,i)=>`<button type="button" aria-pressed="${i===active}">${l}</button>`).join('')}</div>`
const summary = rows => `<div class="summary-box">${rows.map(([l,v])=>`<div class="row between"><span class="muted">${l}</span><strong>${v}</strong></div>`).join('')}</div>`
const plant = () => `<svg viewBox="0 0 240 240" aria-hidden="true"><path d="M120 195V82m0 60c-47 1-71-19-70-55 37-2 67 18 70 55Zm0-23c48-1 71-23 69-60-38 0-64 24-69 60ZM120 87C91 60 95 30 120 14c26 18 29 48 0 73Z" stroke-width="1.3"/><path d="M67 191h106l-14 34H81l-14-34Z" stroke-width="1.5"/><path d="M42 225h156" stroke-width="1"/></svg>`
const save = (destination='timer',label='Gotowe') => nav(destination,label,'btn primary')
const backSettings = nav('settings','Wróć do ustawień','btn ghost')

function header(active='timer') {
  return `<header class="app-header"><a class="brand" href="#timer">Focus Flow</a><nav class="app-nav" aria-label="Główna">${[['timer','Timer'],['statistics','Historia'],['guides','Poradniki']].map(([id,l])=>nav(id,l,id===active?'active':'')).join('')}</nav><div class="row">${nav('cloud','<span class="status-dot"></span><span class="small">Na tym urządzeniu</span>','btn ghost')}${nav('settings',icon('settings'),'icon-btn')}</div></header>`
}
const bottom = active => `<nav class="bottom-nav" aria-label="Główna">${[['timer','Timer'],['statistics','Historia'],['guides','Poradniki']].map(([id,l])=>nav(id,l,id===active?'active':'')).join('')}</nav>`
const footer = () => `<footer class="app-footer"><span>Twój czas. Twoje tempo.</span><div class="row">${nav('cloud','Dane i synchronizacja','')}${nav('shortcuts','Skróty','')}</div></footer>`
function timer(id='timer') {
  const breaking = id==='short-break'||id==='long-break'
  const finished = id==='complete'
  const failed = id==='timer-error'
  const long = id==='long-break'
  const value = breaking?(long?'15:00':'05:00'):finished?'00:00':formatTime(state.remaining)
  return `${header()}<main class="main" id="workspace"><div class="timer-layout"><section class="timer-main"><p class="greeting">Środa, 28 października</p><h1>${breaking?'Czas na oddech.':finished?'Sesja zakończona.':'Jedna rzecz na teraz.'}</h1><div class="task">${icon('check',18)}<input aria-label="Nad czym pracujesz?" value="${esc(state.task)}" data-task></div><div class="phases" role="group" aria-label="Rodzaj sesji">${nav('timer','Skupienie',!breaking?'active':'')}${nav('short-break','Krótka przerwa',breaking&&!long?'active':'')}${nav('long-break','Długa przerwa',long?'active':'')}</div><div class="dial"><span class="eyebrow">${breaking?'Przerwa':finished?'Dobra robota':'Skupienie'}</span><time data-timer>${value}</time><span class="small">${finished?'25 minut zapisane w historii':breaking?'Nie musisz od razu wracać do pracy':'Sesja 1 z 4'}</span></div>${failed?note('Nie udało się zachować ustawień. Wyeksportuj kopię danych przed ponownym uruchomieniem.',true):''}<div class="timer-actions">${finished?nav('short-break','Rozpocznij przerwę','btn primary'):nav(breaking?'break-running':'focus-running',breaking?'Rozpocznij przerwę':'Rozpocznij','btn primary','play')}${nav('timer-settings',icon('settings'),'icon-btn')}</div><div class="row">${nav('audio',icon('sound')+' Dźwięk · deszcz','btn ghost')}${nav('focus-running','Tryb skupienia','btn ghost')}</div></section><aside class="timer-aside"><div class="aside-section day-overview"><div class="stack tight"><span class="eyebrow">Dzisiaj</span><span class="day-total">1 h 15 min</span><p class="small muted">3 zakończone sesje</p></div>${nav('statistics','Zobacz historię','small')}</div><section class="aside-section"><div class="row between"><h3>Małe kroki</h3>${nav('microsteps',icon('plus'),'icon-btn')}</div><div class="checklist"><label><input type="checkbox" checked>Przejrzeć notatki</label><label><input type="checkbox">Wybrać trzy priorytety</label><label><input type="checkbox">Zapisać pierwszy krok</label></div></section><section class="aside-section"><span class="eyebrow">Na krótką przerwę</span><h3>Oderwij wzrok od ekranu.</h3><p class="small muted">Wstań, napij się wody i sprawdź, czego teraz potrzebujesz.</p>${nav('guide-article','Przeczytaj poradnik','small')}</section></aside></div></main>${footer()}${bottom('timer')}`
}
function focus(paused=false,breaking=false) {
  return `<main id="workspace" class="focus-surface"><header class="row between"><a href="#timer" class="brand">Focus Flow</a>${nav('timer','Wyjdź z trybu skupienia','btn ghost')}</header><div class="focus-center"><span class="eyebrow">${paused?'Pauza':breaking?'Przerwa':'Skupienie · sesja 1 z 4'}</span><h1>${breaking?'Zrób miejsce na odpoczynek.':esc(state.task)}</h1><time class="focus-time" data-timer>${breaking?'04:32':formatTime(state.remaining)}</time><div class="row">${nav(paused?'focus-running':'focus-paused',paused?'Wznów':'Pauza','btn soft',paused?'play':'pause')}${nav('reset-confirm','Zakończ','btn ghost')}</div><p class="small muted">${paused?'Wróć, kiedy będziesz gotowy.':'Możesz zrobić pauzę w dowolnym momencie.'}</p></div><footer class="row between"><span class="small muted">Sesja jest zapisywana na tym urządzeniu.</span>${nav('audio',icon('sound'),'icon-btn')}</footer></main>`
}
const sessions = [
 ['10:30','Plan na nowy tydzień','3 kroki · wszystkie ukończone','25 min'],
 ['09:50','Czytanie i notatki','2 kroki · 1 ukończony','25 min'],
 ['09:10','Szkic prezentacji','Bez listy kroków','25 min'],
]
function historyRows(filter='') {
  const list=sessions.filter((s,i)=>(!state.deleted||i!==0)&&s.join(' ').toLowerCase().includes(filter.toLowerCase()))
  return list.length?list.map(s=>`<div class="session"><span class="muted">${s[0]}</span><div><strong>${s[1]}</strong><span class="muted">${s[2]}</span></div><span>${s[3]}</span>${nav('session-edit',icon('dots'),'icon-btn')}</div>`).join(''):`<div class="empty"><h3>Brak pasujących sesji</h3><p class="muted">Spróbuj innego słowa albo wyczyść filtry.</p></div>`
}
function statistics(empty=false) {
 return `${header('statistics')}<main class="main" id="workspace"><div class="page-heading"><div class="stack"><span class="eyebrow">Twoje tempo</span><h1>Historia skupienia</h1><p class="muted">Zobacz, na co znalazł się czas.</p></div><div class="row wrap">${nav('history-filter','Ten tydzień','btn')}${nav('export-card','Podsumowanie','btn','download')}</div></div>${empty?`<div class="empty"><div class="seed">${icon('clock',30)}</div><h2>Pierwsza sesja przed Tobą.</h2><p class="muted">Po zakończeniu timera zobaczysz tutaj swoją historię.</p>${nav('timer','Wróć do timera','btn primary')}</div>`:`<div class="stats-grid"><div class="metric"><span class="small muted">Czas skupienia</span><strong>6 h 40 min</strong><span class="small muted">W tym tygodniu</span></div><div class="metric"><span class="small muted">Zakończone sesje</span><strong>16</strong><span class="small muted">Średnio 25 minut</span></div><div class="metric"><span class="small muted">Dni z sesją</span><strong>4</strong><span class="small muted">Bez presji na ciągłość</span></div></div><div class="two-col"><section class="chart"><div class="row between"><h3>Ten tydzień</h3><span class="small muted">Minuty</span></div><div class="bars">${[50,90,75,125,60,0,0].map((n,i)=>`<div class="bar-col"><span>${n||'—'}</span><div class="bar ${i===2?'today':''}" style="height:${Math.max(3,n*.8)}px"></div><span>${['Pn','Wt','Śr','Cz','Pt','So','Nd'][i]}</span></div>`).join('')}</div></section><section class="chart stack"><h3>Na co był czas</h3>${[['Pisanie i prezentacje','2 h 30 min'],['Czytanie i notatki','1 h 40 min'],['Planowanie','1 h 15 min'],['Inne','1 h 15 min']].map(([l,v])=>`<div class="row between small"><span>${l}</span><strong>${v}</strong></div>`).join('')}<div class="divider"></div>${nav('activity','Aktywność i obserwacje','small')}</section></div><section class="history"><div class="history-head"><h2 class="grow">Sesje</h2><input type="search" class="input search" aria-label="Szukaj w całej historii" placeholder="Szukaj w całej historii" data-history-search>${nav('history-filter',icon('search'),'icon-btn')}</div><p class="eyebrow" style="margin-bottom:16px">Dzisiaj · 28 października</p><div id="session-list">${historyRows()}</div><div class="row between" style="margin-top:20px"><span class="small muted">3 z 16 sesji</span>${action('more-sessions','Pokaż więcej','btn ghost')}</div></section>`}</main>${footer()}${bottom('statistics')}`
}
const guideCards = [
 ['ZACZĄĆ','Mały krok wystarczy','Jak rozłożyć zadanie na pierwszy wykonalny ruch.','4 min'],
 ['ODPOCZĄĆ','Przerwa, która daje oddech','Kilka sposobów na odejście od ekranu.','3 min'],
 ['UPORZĄDKOWAĆ','Mniej otwartych spraw','Zapisz to, do czego chcesz wrócić później.','5 min'],
 ['ZAPLANOWAĆ','Realistyczny plan dnia','Zostaw miejsce na przerwy i zmianę planów.','4 min'],
 ['SKUPIĆ SIĘ','Przygotuj miejsce do pracy','Usuń jedną przeszkodę przed rozpoczęciem.','3 min'],
 ['WRÓCIĆ','Powrót po przerwie','Wybierz kolejny krok bez nadrabiania wszystkiego.','4 min'],
]
function guides(category=false,search=false) {
 return `${header('guides')}<main class="main" id="workspace">${search?'<div class="planned"><span class="badge">3.3</span>Projekt rozbudowanej biblioteki</div>':''}<div class="page-heading"><div class="stack"><span class="eyebrow">Biblioteka</span><h1>${category?'Zacząć spokojniej':'Poradniki na Twój moment'}</h1><p class="muted">Krótka lektura. Jeden pomysł do wypróbowania.</p></div>${nav('guide-search','Szukaj poradnika','btn','search')}</div>${search?`<label class="field"><span class="field-label">Czego szukasz?</span><input class="input" type="search" placeholder="Np. przerwa, planowanie, rozpoczęcie" data-guide-search></label><div class="divider" style="margin:24px 0"></div>`:`<section class="guide-feature"><div class="stack"><span class="eyebrow">Na początek · 4 min czytania</span><h2>Nie potrzebujesz idealnego momentu.</h2><p class="muted">Zacznij od jednej małej rzeczy. Praktyczny przewodnik po wybieraniu pierwszego kroku.</p><div>${nav('guide-article','Przeczytaj poradnik','btn primary')}</div></div><div class="guide-art">${plant()}</div></section>`}<div class="pill-options" style="margin-bottom:24px" aria-label="Kategorie poradników">${[['guides','Wszystkie'],['guide-category','Zacząć'],['guide-category','Odpocząć'],['guide-category','Uporządkować']].map(([id,l])=>nav(id,l,'btn')).join('')}</div><div class="guide-grid" id="guide-list">${guideCards.map(([tag,t,d,time])=>`<article class="guide-card" data-guide="${(t+' '+d).toLowerCase()}"><span class="eyebrow">${tag}</span>${nav('guide-article',t,'')}<p class="small muted">${d}</p><span class="small muted">${time} czytania</span></article>`).join('')}</div><div id="guide-no-results" class="empty" hidden><h2>Nie ma takiego poradnika.</h2><p class="muted">Spróbuj krótszego hasła lub innego słowa.</p></div></main>${footer()}${bottom('guides')}`
}
function article() {
 return `${header('guides')}<main class="main" id="workspace"><article class="article stack"><div>${nav('guides','← Wszystkie poradniki','small')}</div><span class="eyebrow">Zacząć · 4 min czytania</span><h1>Zacznij od jednego małego kroku.</h1><p class="lead">Wybierz działanie, które możesz wykonać teraz. Reszta zadania może poczekać.</p><div class="row between"><span class="small muted">Przegląd treści: 28.10.2026</span>${nav('guide-bookmarked','Zapisz','btn ghost','book')}</div><div class="divider"></div><section><h2>Na czym dziś chcesz się skupić?</h2><p>Zamiast wpisywać „projekt”, nazwij najbliższe działanie. Na przykład: „otworzyć notatki i wybrać trzy najważniejsze punkty”.</p><p>Ustaw długość sesji, która pasuje do Twojej energii i planu dnia. Możesz ją przerwać lub zmienić.</p></section><section><h2>Wypróbuj przy następnej sesji</h2><ol><li>Zapisz jedno konkretne zadanie.</li><li>Podziel je na najwyżej trzy małe kroki.</li><li>Rozpocznij od pierwszego. Po sesji zdecyduj, co dalej.</li></ol>${nav('timer','Przejdź do timera','btn primary')}</section><section><h2>Gdy nadal trudno zacząć</h2><p>Zmniejsz pierwszy krok albo zrób przerwę. Trudność z rozpoczęciem nie oznacza, że musisz zmuszać się do dłuższej sesji.</p></section><section>${note('To ogólne wskazówki dotyczące pracy z zadaniami. Timer i poradniki nie służą do diagnozowania ani leczenia.')}<p class="small muted" style="margin-top:18px">Układ demonstracyjny. Przed wdrożeniem każda treść zachowa sprawdzone przypisy z biblioteki aplikacji.</p></section><section><span class="eyebrow">Czytaj dalej</span>${row('guide-article','Przerwa, która daje oddech','3 min czytania','book')}</section></article></main>${footer()}${bottom('guides')}`
}

register('timer','Timer · gotowy','Timer','page',()=>timer())
register('short-break','Krótka przerwa','Timer','page',()=>timer('short-break'))
register('long-break','Długa przerwa','Timer','page',()=>timer('long-break'))
register('focus-running','Sesja · tryb skupienia','Timer','page',()=>focus())
register('focus-paused','Sesja · pauza','Timer','page',()=>focus(true))
register('break-running','Przerwa · w trakcie','Timer','page',()=>focus(false,true))
register('complete','Zakończona sesja','Timer','page',()=>timer('complete'))
register('reset-confirm','Zakończyć sesję?','Timer','modal',()=>`<p class="muted">Pozostało 18 minut i 42 sekundy. Możesz wrócić do timera lub zakończyć tę sesję.</p>${summary([['Zadanie',esc(state.task)],['Zapisany czas','6 min']])}${note('Dotychczasowy czas pozostanie w historii. Nowa sesja zacznie się od początku.')}`,()=>nav('focus-paused','Wróć','btn')+nav('complete','Zakończ sesję','btn primary'))
register('microsteps','Małe kroki','Timer','modal',()=>`<p class="muted">Rozpisz najbliższe działania. Możesz zmienić je podczas sesji.</p>${field('Krok 1','Przejrzeć notatki')}${field('Krok 2','Wybrać trzy priorytety')}${field('Krok 3','Zapisać pierwszy krok')}${action('add-step','Dodaj krok','btn ghost','plus')}`,()=>save())
register('timer-settings','Ustawienia timera','Ustawienia','modal',()=>`<p class="muted">Dopasuj rytm do swojego dnia.</p><div class="three-col">${[['Skupienie',25],['Krótka przerwa',5],['Długa przerwa',15]].map(([l,v])=>`<label class="field number-field"><span class="small">${l}</span><input type="number" min="1" max="180" value="${v}"><small>minut</small></label>`).join('')}</div>${field('Długa przerwa po','4','number','Liczba zakończonych sesji skupienia.')}${toggle('Automatycznie rozpoczynaj przerwy','Po zakończeniu sesji skupienia.',false)}${toggle('Automatycznie rozpoczynaj skupienie','Po zakończeniu przerwy.',false)}${note('Zmiany czasu zastosujesz do następnej sesji. Bieżący timer pozostanie bez zmian.')}`,()=>save('timer','Zapisz ustawienia'))
register('statistics','Historia · z danymi','Historia','page',()=>statistics())
register('history-empty','Historia · pusta','Historia','page',()=>statistics(true))
register('history-filter','Filtry historii','Historia','modal',()=>`<div class="field"><span class="field-label">Zakres dat</span>${options('Zakres',['Dzisiaj','Tydzień','Miesiąc','Własny'],1)}</div>${field('Od','2026-10-26','date')}${field('Do','2026-11-01','date')}${field('Zadanie','Planowanie')}${note('Wyszukiwanie obejmuje całą historię, również sesje spoza widocznej strony.')}`,()=>nav('statistics','Wyczyść','btn')+nav('statistics','Zastosuj','btn primary'))
register('session-edit','Edytuj sesję','Historia','modal',()=>`${field('Zadanie','Plan na nowy tydzień')}${field('Data','2026-10-28','date')}${field('Czas skupienia w minutach','25','number')}<div class="field"><span class="field-label">Ukończone kroki</span><div class="checklist"><label><input type="checkbox" checked>Przejrzeć notatki</label><label><input type="checkbox" checked>Wybrać trzy priorytety</label></div></div>${nav('session-delete','Usuń tę sesję','btn danger')}`,()=>nav('statistics','Anuluj','btn')+action('save-session','Zapisz','btn primary'))
register('session-delete','Usunąć tę sesję?','Historia','modal',()=>`${summary([['Zadanie','Plan na nowy tydzień'],['Czas','25 min'],['Data','28.10.2026, 10:30']])}<p class="muted">Sesja zniknie z historii i podsumowań. Jeśli korzystasz z synchronizacji, usunięcie dotrze też na pozostałe urządzenia.</p>${note('Tej operacji nie można cofnąć w aplikacji. Zachowaj eksport, jeśli chcesz mieć kopię.',true)}`,()=>nav('session-edit','Zachowaj sesję','btn')+action('delete-session','Usuń sesję','btn danger'))
register('export-card','Udostępnij podsumowanie','Historia','modal',()=>`<p class="muted">Obraz zawiera tylko poniższe informacje. Bez nazw zadań i danych konta.</p><div class="export-card"><span>Focus Flow</span><span class="small">26 października – 1 listopada</span><strong>6 h 40 min</strong><span>16 sesji · Twój czas, Twoje tempo.</span></div>${toggle('Pokaż liczbę sesji','',true)}`,()=>nav('statistics','Wróć','btn')+action('export-preview','Pobierz PNG','btn primary','download'))
register('activity','Aktywność i obserwacje','Historia','page',()=>`${header('statistics')}<main class="main" id="workspace"><div class="page-heading"><div class="stack"><span class="eyebrow">Szerszy obraz</span><h1>Rytm ostatnich tygodni</h1><p class="muted">Każdy dzień może wyglądać inaczej.</p></div>${nav('statistics','Wróć do historii','btn')}</div><div class="two-col"><section class="chart"><h3>Ostatnie 8 tygodni</h3><div class="heatmap">${Array.from({length:56},(_,i)=>`<i class="${i%3===0?'hot':''}"></i>`).join('')}</div><p class="small muted" style="margin-top:16px">Ciemniejszy kolor oznacza więcej minut. Puste dni nie obniżają wyniku.</p></section><section class="chart stack"><h3>Twoje obserwacje</h3><p>Najwięcej czasu na sesje znalazło się we wtorek.</p><p class="small muted">To opis zapisanej historii, bez przewidywania Twojej produktywności.</p>${note('Masz za mało sesji, żeby porównać pory dnia. Wróć tu po kolejnych sesjach.')}</section></div></main>${footer()}${bottom('statistics')}`)
register('guides','Biblioteka poradników','Poradniki','page',()=>guides())
register('guide-category','Kategoria poradników','Poradniki','page',()=>guides(true))
register('guide-article','Czytanie poradnika','Poradniki','page',article)
register('guide-not-found','Poradnik niedostępny','Poradniki','page',()=>`${header('guides')}<main id="workspace" class="main empty"><div class="seed">${icon('book',28)}</div><h1>Nie znaleźliśmy tego poradnika.</h1><p class="muted">Link mógł się zmienić. Pozostałe poradniki są dostępne w bibliotece.</p>${nav('guides','Otwórz bibliotekę','btn primary')}</main>${footer()}`)
register('settings','Ustawienia','Ustawienia','modal',()=>`<p class="muted">Ułóż Focus Flow po swojemu.</p><div class="settings-list">${row('timer-settings','Timer','Czas sesji i przerw','clock')}${row('goals','Cel dzienny','Opcjonalny punkt odniesienia','clock')}${row('appearance','Wygląd','Motyw, kolory i podgląd','eye')}${row('audio','Dźwięk','Tło, głośność i własne pliki','sound')}${row('language','Język','Polski · English · Español · 简体中文','globe')}${row('accessibility','Dostępność','Ruch, narracja i komunikaty','eye')}${row('shortcuts','Skróty klawiaturowe','Sterowanie bez myszy','desktop')}${row('notifications','Powiadomienia','Uprawnienia tego urządzenia','settings')}${row('cloud','Konto i synchronizacja','Opcjonalne połączenie urządzeń','cloud')}${row('data','Kopie i eksport','Twoje dane w otwartych formatach','download')}${row('desktop','Aplikacja desktopowa','Autostart, mini timer i skróty','desktop')}</div><details><summary>Zaawansowane</summary><div class="settings-list">${row('webhook','Webhook','Własne integracje','settings')}${row('peer','Połączenie lokalne','Eksperymentalne · P2P','desktop')}${row('recovery','Odzyskiwanie danych','Eksport i bezpieczne ponowienie','shield')}</div></details>`,()=>save())
register('appearance','Wygląd','Ustawienia','modal',()=>`<p class="muted">Kolory zmieniają cały interfejs. Wybierz wariant, przy którym wygodnie Ci się pracuje.</p><div class="theme-grid">${themes.map(t=>`<label class="theme-choice"><span class="preview" style="--swatch-page:${t.colors[0]};--swatch-ink:${t.colors[1]};--swatch-accent:${t.colors[2]};--swatch-control:${t.colors[3]}"><span class="sample-dial">25</span><span class="sample-lines"><i></i><i></i></span></span><span class="theme-title"><input type="radio" name="theme" value="${t.id}" ${state.theme===t.id?'checked':''}>${t.name}</span><small class="muted">${t.desc}</small></label>`).join('')}</div>${toggle('Dopasuj do systemu','Jasny i ciemny wariant zgodnie z urządzeniem.',false)}${nav('theme-comparison','Porównaj wszystkie motywy','small')}`,()=>backSettings+save('timer','Zastosuj'))
register('theme-comparison','Porównanie motywów','Ustawienia','page',()=>`${header()}<main class="main" id="workspace"><div class="page-heading"><div class="stack"><span class="eyebrow">Siedem wariantów</span><h1>Wybierz swój odcień skupienia.</h1><p class="muted">Podgląd zawiera tekst, formularz, akcent i stan błędu.</p></div>${nav('appearance','Wybór wyglądu','btn')}</div><div class="guide-grid">${themes.map(t=>`<section data-theme="${t.id}" class="chart stack" style="background:var(--page);color:var(--ink);border-color:var(--control)"><span class="eyebrow">${t.name}</span><h2>Jedna rzecz na teraz.</h2><p class="muted small">${t.desc}</p><div class="task"><span class="small">Plan na nowy tydzień</span></div><div class="row wrap"><button class="btn primary" data-theme-select="${t.id}">Wybierz</button><span class="chip">Sesja 1 z 4</span></div><span style="color:var(--danger)" class="small">Nie udało się połączyć. Dane są na urządzeniu.</span></section>`).join('')}</div></main>${footer()}`)
register('language','Język','Ustawienia','modal',()=>`<p class="muted">Wybór języka nie zmienia zapisanej historii.</p><div class="choice-list">${[['pl','Polski','Polski'],['en','English','Angielski'],['es','Español','Hiszpański'],['zh-Hans','简体中文','Chiński uproszczony']].map(([v,l,d])=>`<label class="choice"><input type="radio" name="language" value="${v}" ${state.language===v?'checked':''}><span>${l}<small>${d}</small></span></label>`).join('')}</div>${note('Ten prototyp pokazuje polski układ. Działająca aplikacja 3.0 ma cztery pełne wersje językowe.')}`,()=>backSettings+save('settings'))
register('accessibility','Dostępność','Ustawienia','modal',()=>`<div class="field"><span class="field-label">Szczegółowość narracji</span>${options('Narracja',['Minimalna','Standardowa','Szczegółowa'],1)}<small>Komunikaty przekazywane czytnikowi ekranu.</small></div>${toggle('Głosowe komunikaty timera','Opcjonalny głos dostępny na urządzeniu.',true)}${action('voice-preview','Odtwórz próbkę głosu','btn','sound')}${toggle('Ogranicz animacje','Uwzględnij też ustawienia systemu.',false)}${toggle('Pokaż powitanie','Krótki tekst na ekranie głównym.',true)}${nav('voice-unavailable','Gdy brak dostępnego głosu','small')}`,()=>backSettings+save('settings'))
register('voice-unavailable','Głos niedostępny','Ustawienia','modal',()=>`${note('Na tym urządzeniu nie ma głosu dla wybranego języka.',true)}<p class="muted">Komunikaty tekstowe i obsługa czytnika ekranu pozostają dostępne. Możesz dodać głos w ustawieniach systemu albo wyłączyć komunikaty głosowe.</p>${toggle('Głosowe komunikaty timera','',false)}`,()=>save('accessibility','Wróć do dostępności'))
register('shortcuts','Skróty klawiaturowe','Ustawienia','modal',()=>`<p class="muted">Skróty aplikacji działają poza polami tekstowymi.</p><div class="settings-list">${[['Start / pauza','Spacja'],['Reset timera','R'],['Tryb skupienia','F'],['Dźwięk tła','M'],['Zamknij okno','Esc']].map(([l,k])=>`<div class="switch-row"><span class="small">${l}</span><button class="kbd" data-action="shortcut-edit">${k}</button></div>`).join('')}</div>${nav('shortcut-conflict','Zmień skrót','btn')}${action('shortcut-reset','Przywróć domyślne','btn ghost')}`,()=>backSettings+save('settings'))
register('shortcut-conflict','Zmień skrót','Ustawienia','modal',()=>`${field('Wybrana czynność','Tryb skupienia')}${field('Naciśnij nowy skrót','Spacja')}${note('Spacja jest już przypisana do startu i pauzy. Wybierz inny klawisz.',true)}<p class="small muted">Skróty systemowe są ustawiane osobno w aplikacji desktopowej.</p>`,()=>nav('shortcuts','Anuluj','btn')+'<button class="btn primary" disabled>Zapisz skrót</button>')
register('audio','Dźwięk','Ustawienia','modal',()=>`<div class="field"><span class="eyebrow">Tło</span>${options('Dźwięk tła',['Wyłączony','Deszcz','Las','Potok','Morze','Brązowy szum'],1)}</div><div class="field"><span class="eyebrow">Własne pliki</span><div class="row between small"><span>Spokojny poranek.mp3</span>${action('remove-sound','Usuń','btn ghost')}</div>${action('add-sound','Dodaj plik audio','btn','plus')}<small>Plik pozostaje na tym urządzeniu.</small></div><div class="divider"></div><div class="field"><span class="field-label">Dźwięki binauralne</span>${options('Binauralne',['Wyłączone','Alpha','Theta'])}<small>Wymagają słuchawek. Nie stanowią terapii.</small></div>${range('Barwa dźwięku',800,200,1200,' Hz',['Ciepła','Jasna'])}${range('Głośność',35,0,100,'%',['Ciszej','Głośniej'])}<details><summary class="small">Licencje nagrań</summary><p class="small muted">Nagrania tła: Moodist. W aplikacji zachowujemy przypisanie źródeł i właściwe warunki licencyjne każdego pliku.</p></details>${nav('audio-error','Stan błędu pliku audio','small')}`,()=>save())
register('audio-error','Nie można odtworzyć pliku','Ustawienia','modal',()=>`${note('Ten format audio nie jest obsługiwany lub plik jest uszkodzony.',true)}<p class="muted">Wybierz inny plik albo wróć do dźwięków tła. Timer działa dalej.</p>`,()=>nav('audio','Wróć','btn')+action('add-sound','Wybierz inny plik','btn primary'))
register('notifications','Powiadomienia','Ustawienia','modal',()=>`${summary([['Uprawnienie','Nieustawione']])}<p class="muted">Powiadomienie może poinformować o zakończeniu sesji, gdy pracujesz w innym oknie.</p>${note('Po wybraniu przycisku aplikacja poprosi przeglądarkę lub system o uprawnienie.')}${nav('notifications-granted','Poproś o uprawnienie','btn primary')}${nav('notifications-denied','Zobacz stan odmowy','small')}`,()=>backSettings+save('settings'))
register('notifications-granted','Powiadomienia włączone','Ustawienia','modal',()=>`${summary([['Uprawnienie','Dozwolone']])}${note('Urządzenie może wyświetlać komunikaty o zakończeniu sesji.')}${action('notification-test','Wyślij próbne powiadomienie','btn')}`,()=>backSettings+save('settings'))
register('notifications-denied','Powiadomienia zablokowane','Ustawienia','modal',()=>`${note('Przeglądarka lub system blokuje powiadomienia.',true)}<p class="muted">Otwórz ustawienia uprawnień witryny lub aplikacji w systemie. Zmień dostęp do powiadomień, a potem sprawdź ponownie.</p>${nav('notifications','Sprawdź uprawnienie','btn')}`,()=>backSettings+save('settings'))

register('cloud','Konto i synchronizacja','Synchronizacja','modal',()=>`<div class="row"><span class="glyph">${icon('cloud',28)}</span><h2>Twoje sesje, na Twoich urządzeniach.</h2></div><p class="muted">Bez konta możesz korzystać z timera, historii i eksportu. Konto Google służy do opcjonalnej synchronizacji.</p>${nav('cloud-connecting','Kontynuuj z Google','btn primary')}${note('Połączenie wymaga internetu. Wybór konta odbywa się w oknie Google, a na desktopie w przeglądarce systemowej.')}<div class="settings-list">${row('data','Zachowaj kopię','Eksport JSON przed połączeniem','download')}${row('cloud-config-error','Problem z logowaniem','Pomoc i ponowienie','shield')}</div>`,()=>save('timer','Korzystaj bez konta'))
register('cloud-connecting','Łączenie konta','Synchronizacja','modal',()=>`<div class="empty" style="padding:28px 0"><div class="loading-ring"></div><h2>Dokończ logowanie w Google.</h2><p class="muted">Po wyborze konta wróć do aplikacji. Twoja lokalna historia pozostaje zachowana.</p></div>${note('W prototypie logowanie jest symulowane. Żadne okno Google nie jest otwierane.')}`,()=>nav('cloud','Anuluj','btn')+nav('cloud-connected','Podgląd po połączeniu','btn primary'))
register('cloud-connected','Konto połączone','Synchronizacja','modal',()=>`${summary([['Konto','tester@example.invalid'],['Stan','Zsynchronizowano'],['Ostatnia synchronizacja','Dzisiaj, 10:58']])}${action('sync-now','Synchronizuj teraz','btn primary','cloud')}${toggle('Maskuj nazwy zadań w chmurze','Nazwy pozostają czytelne na tym urządzeniu.',false)}${note('Połączenie nie jest szyfrowaniem end-to-end. Maskowanie nie ukrywa czasu sesji ani danych konta.')}<div class="settings-list">${row('account-change','Zmień konto','Najpierw zachowamy kopię lokalną','globe')}${row('cloud-disconnect','Wyloguj się','Zachowaj historię na urządzeniu','shield')}${row('cloud-delete','Usuń dane z chmury','Osobna decyzja od wylogowania','shield')}${row('cloud-memory','Sesja bez trwałego logowania','Gdy pamięć konta jest niedostępna','shield')}</div>`,()=>save())
register('cloud-pending','Zmiany czekają na wysłanie','Synchronizacja','modal',()=>`${summary([['Konto','tester@example.invalid'],['Stan','3 zmiany oczekujące']])}<p class="muted">Najnowsze sesje są zapisane na urządzeniu. Aplikacja spróbuje wysłać je po odzyskaniu połączenia.</p>${nav('cloud-offline','Zobacz tryb offline','btn')}`,()=>save())
register('cloud-offline','Synchronizacja · offline','Synchronizacja','modal',()=>`${note('Brak połączenia. Lokalne dane są dostępne.')}<p class="muted">Możesz pracować dalej. Edycje i usunięcia zostaną wysłane po połączeniu z internetem.</p>${summary([['Oczekujące zmiany','3'],['Ostatnie połączenie','Dzisiaj, 10:58']])}${nav('cloud-connected','Spróbuj ponownie','btn primary')}${nav('data','Eksportuj kopię','btn')}`,()=>save())
register('cloud-config-error','Nie udało się połączyć','Synchronizacja','modal',()=>`${note('Logowanie nie zostało ukończone.',true)}<p class="muted">Sprawdź połączenie i ponów logowanie. Jeśli problem wraca, korzystaj lokalnie i zachowaj eksport danych.</p><p class="error-code">AUTH_POPUP_CLOSED</p>${nav('cloud-connecting','Spróbuj ponownie','btn primary')}`,()=>save('timer','Wróć do timera'))
register('account-change','Zmiana konta','Synchronizacja','modal',()=>`<p class="muted">Przed zmianą konta zachowaj lokalną kopię. Dane bieżącego konta pozostają przypisane do niego.</p>${summary([['Bieżące konto','tester@example.invalid'],['Sesje lokalne','16']])}${action('backup-preview','Pobierz kopię JSON','btn','download')}${note('Na kolejnym ekranie wybierzesz konto w Google. Nie połączymy historii dwóch kont bez Twojej decyzji.')}`,()=>nav('cloud-connected','Anuluj','btn')+nav('account-choice','Kontynuuj','btn primary'))
register('account-choice','Historia po zmianie konta','Synchronizacja','modal',()=>`<p class="muted">Wybierz, co zrobić z lokalną historią przed połączeniem z nowym kontem.</p><div class="choice-list"><label class="choice"><input type="radio" name="account-history" checked><span>Oddziel historie<small>Otwórz dane nowego konta. Obecną historię zachowaj w kopii.</small></span></label><label class="choice"><input type="radio" name="account-history"><span>Przenieś lokalne sesje<small>Połącz je z nowym kontem po sprawdzeniu kopii.</small></span></label></div>${note('To projekt jawnego wyboru dla 3.1. Izolacja kont i kopia pozostają wymagane.')}`,()=>nav('account-change','Wróć','btn')+nav('cloud-connected','Potwierdź wybór','btn primary'))
register('cloud-disconnect','Wylogować się?','Synchronizacja','modal',()=>`<p class="muted">Sesje pozostaną na urządzeniu. Automatyczna synchronizacja zatrzyma się do następnego logowania.</p>${note('Wylogowanie nie usuwa konta Google ani danych zapisanych w chmurze.')}`,()=>nav('cloud-connected','Zostań','btn')+nav('cloud','Wyloguj się','btn primary'))

register('data','Kopie i eksport','Dane','modal',()=>`<p class="muted">Zachowaj historię w otwartym formacie. JSON służy też do odtworzenia danych.</p><div class="format-grid">${action('backup-preview','JSON · pełna kopia','btn','download')}${action('export-preview','CSV · sesje','btn','download')}${action('export-preview','Markdown','btn','download')}${action('export-preview','iCalendar','btn','download')}</div>${summary([['Zawartość kopii','16 sesji + ustawienia'],['Zakres eksportu','Cała historia']])}${nav('import-preview','Importuj kopię JSON','btn primary')}${note('Eksport zawiera prywatne nazwy zadań. Przechowuj go w zaufanym miejscu.')}${nav('recovery','Pomoc w odzyskiwaniu danych','small')}`,()=>backSettings+save('settings'))
register('import-preview','Sprawdź import','Dane','modal',()=>`${summary([['Plik','focus-flow-backup.json'],['Sesje w pliku','500'],['Nowe sesje','497'],['Istniejące identyfikatory','3']])}<p class="muted">Sprawdź podsumowanie przed odtworzeniem. Bieżąca historia zostanie zabezpieczona kopią.</p>${note('Podgląd importu jest propozycją 3.1. Nie odczytujemy tutaj plików ani danych aplikacji.')}`,()=>nav('data','Anuluj','btn')+nav('import-success','Importuj','btn primary'))
register('import-success','Kopia odtworzona','Dane','modal',()=>`<div class="empty" style="padding:24px 0"><div class="seed">${icon('check',30)}</div><h2>Historia jest gotowa.</h2><p class="muted">Dodano 497 sesji. Kopia poprzedniego stanu została zachowana.</p></div>${nav('statistics','Otwórz historię','btn primary')}`,()=>save('data','Wróć do kopii'))
register('import-error','Nie można odczytać kopii','Dane','modal',()=>`${note('Plik nie jest poprawną kopią Focus Flow.',true)}<p class="muted">Sprawdź, czy wybrano plik JSON z eksportu aplikacji. Bieżące dane nie zostały zmienione.</p>${nav('import-preview','Wybierz inny plik','btn primary')}`,()=>save('data','Wróć do kopii'))
register('recovery','Odzyskiwanie danych','Dane','modal',()=>`<p class="muted">Zanim odświeżysz lub przywrócisz kopię, zachowaj obecny stan.</p><ol class="small"><li>Wyeksportuj dostępną historię do JSON.</li><li>Zachowaj kopię całego katalogu danych desktopu, jeśli go używasz.</li><li>Otwórz właściwy plik kopii i sprawdź wynik importu.</li></ol>${action('backup-preview','Eksportuj dostępne dane','btn','download')}${nav('import-preview','Przywróć z kopii','btn primary')}${note('Nie usuwaj pamięci przeglądarki ani katalogu aplikacji przed wykonaniem kopii.')}`,()=>save('timer','Wróć do aplikacji'))

register('desktop','Aplikacja desktopowa','Desktop i integracje','modal',()=>`${toggle('Uruchamiaj po zalogowaniu','Dostępne w zainstalowanej aplikacji.',false)}${toggle('Nie usypiaj podczas sesji','Tylko gdy timer pracuje.',true)}<div class="settings-list">${row('mini','Pływający mini timer','Małe okno nad innymi aplikacjami','desktop')}${row('tray','Menu w zasobniku','Sterowanie z poziomu systemu','desktop')}</div><div class="summary-box"><span class="field-label">Skróty systemowe</span><p class="small muted">Ctrl / Cmd + Shift + F · pokaż aplikację</p><p class="small muted">Ctrl / Cmd + Shift + M · mini timer</p></div>${nav('desktop-error','Stan niedostępnej funkcji OS','small')}`,()=>backSettings+save('settings'))
register('mini','Pływający mini timer','Desktop i integracje','page',()=>`${header()}<main id="workspace" class="main"><p class="platform-caption">Desktop · zawartość pływającego okna</p><div class="mini-preview"><div class="row between"><span class="small">Skupienie</span>${nav('timer',icon('close'),'icon-btn')}</div><time>18:42</time><p class="small muted" style="text-align:center">Plan na nowy tydzień</p><div class="row" style="justify-content:center;margin-top:18px">${action('mini-pause','Pauza','btn primary','pause')}${nav('timer','Otwórz','btn')}</div></div><p class="platform-caption">Ramkę okna, zmianę rozmiaru i pozycję obsługuje system.</p></main>${footer()}`)
register('tray','Menu zasobnika','Desktop i integracje','page',()=>`${header()}<main id="workspace" class="main stack"><p class="platform-caption">Desktop · zestaw poleceń w natywnym menu systemowym</p><div class="tray-preview"><button data-action="tray-open">Pokaż Focus Flow</button><button data-action="tray-pause">Pauza / wznów</button><button data-action="tray-reset">Reset timera</button><div class="divider"></div><button data-action="tray-mini">Mini timer</button><button data-action="tray-settings">Ustawienia</button><div class="divider"></div><button data-action="tray-quit">Zakończ</button></div><p class="platform-caption">Wygląd menu i ikony jest zgodny z systemem Linux / Windows / macOS.</p></main>${footer()}`)
register('desktop-error','Funkcja systemowa niedostępna','Desktop i integracje','modal',()=>`${note('Nie udało się zmienić ustawienia systemowego.',true)}<p class="muted">Timer i lokalna historia nadal działają. Sprawdź uprawnienia aplikacji i spróbuj ponownie.</p>${nav('desktop','Spróbuj ponownie','btn primary')}`,()=>save('settings'))
