register('garden','Twój ogród','Planowane 3.2–3.4','page',()=>`${header()}<main class="main" id="workspace"><div class="planned"><span class="badge">3.2</span>Planowana funkcja · dobrowolna</div><div class="page-heading"><div class="stack"><span class="eyebrow">Bez pośpiechu</span><h1>Twój mały ogród.</h1><p class="muted">Zachowaj ślad czasu, który znalazł się na ważne rzeczy.</p></div>${nav('garden-plants','Wybierz roślinę','btn')}</div><div class="two-col"><div class="garden-scene">${plant()}</div><section class="stack"><h2>Szałwia ma się dobrze.</h2><p class="muted">Ostatnia sesja dodała kolejny listek. Rośliny nie więdną, gdy robisz przerwę.</p>${note('Nie ma serii dni, utraty postępów ani obowiązku wracania. Ogród możesz wyłączyć w każdej chwili.')}${toggle('Pokaż ogród w aplikacji','Dane ogrodu pozostają lokalne.',true)}${nav('timer','Wróć do timera','btn primary')}</section></div></main>${footer()}`,null,'3.2')
