register('about','Strona o projekcie · /about','Planowane 3.2–3.4','page',()=>`${header()}<main class="main" id="workspace"><div class="planned"><span class="badge">3.4</span>Planowana strona · focusflow.ink/about</div><section class="about-hero"><div class="stack"><span class="eyebrow">Focus Flow</span><h1>Miejsce na to,<br>co teraz ważne.</h1><p>Prosty timer, spokojne dźwięki i historia Twojej pracy. Zacznij od jednej sesji, we własnym tempie.</p><div class="row wrap">${nav('timer','Otwórz aplikację','btn primary','arrow')}${nav('about-download','Wersja na komputer','btn')}</div><span class="small muted">Bez obowiązkowego konta. Z danymi na Twoim urządzeniu.</span></div><div class="guide-art" style="min-height:360px">${plant()}</div></section><div class="guide-grid"><section class="guide-card"><span class="eyebrow">01 · Rytm</span><h2>Jedna sesja na raz.</h2><p class="muted">Dopasuj skupienie i przerwy do swojego dnia.</p></section><section class="guide-card"><span class="eyebrow">02 · Spokój</span><h2>Mniej rzeczy na ekranie.</h2><p class="muted">Wybierz dźwięk, motyw i mały krok do wykonania.</p></section><section class="guide-card"><span class="eyebrow">03 · Własność</span><h2>Twoja historia należy do Ciebie.</h2><p class="muted">Eksportuj dane. Synchronizację włącz, jeśli jej potrzebujesz.</p></section></div><section class="article stack" style="margin:60px auto"><h2>Kilka pytań przed pierwszą sesją</h2><details><summary>Czy potrzebuję konta?</summary><p class="muted">Nie. Konto jest opcjonalne i służy do synchronizacji.</p></details><details><summary>Czy aplikacja działa offline?</summary><p class="muted">Po pierwszym wczytaniu możesz używać timera i lokalnych danych bez internetu.</p></details><details><summary>Gdzie są przechowywane moje dane?</summary><p class="muted">Na urządzeniu. Po włączeniu synchronizacji jej zakres jest przesyłany do skonfigurowanej chmury. Nie jest to szyfrowanie end-to-end.</p></details>${nav('timer','Znajdź czas na pierwszą sesję','btn primary')}</section></main>${footer()}`,null,'3.4')
register('about-download','Wybór wersji desktopowej','Planowane 3.2–3.4','page',()=>`${header()}<main class="main" id="workspace"><div class="planned"><span class="badge">3.4</span>Projekt sekcji pobierania</div><div class="page-heading"><div class="stack"><span class="eyebrow">Na komputer</span><h1>Wybierz swoją wersję.</h1><p class="muted">Aplikacja web pozostaje dostępna w przeglądarce.</p></div>${nav('timer','Otwórz web/PWA','btn primary')}</div><div class="guide-grid">${[['Windows','x64 · instalator NSIS'],['Linux','x86_64 · AppImage / Debian'],['macOS','ARM64 · eksperymentalna']].map(([n,d])=>`<section class="chart stack"><h2>${n}</h2><p class="muted small">${d}</p>${action('download-preview','Pobierz instalator','btn')}${nav('data','Jak zachować kopię','small')}</section>`).join('')}</div>${note('Prototyp nie pobiera instalatorów. Oficjalne pliki 3.0, sumy SHA-256 i informacje o niepodpisanych paczkach są w wydaniu GitHub.')}</main>${footer()}`,null,'3.4')

