function routeId(){const id=location.hash.slice(1)||'timer';return routes.has(id)?id:'guide-not-found'}
function formatTime(n){return `${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`}
function catalog(){
 const groups=[...new Set([...routes.values()].map(r=>r.group))]
 document.querySelector('#screen-count').textContent=`(${routes.size})`
 document.querySelector('#catalog').innerHTML=`<h2>Mapa interfejsów</h2><p class="small muted">Projekt 3.1 oraz osobno oznaczone propozycje 3.2–3.4. Dane demonstracyjne, bez połączenia z kontami i usługami.</p>${groups.map(g=>`<h3>${g}</h3>${[...routes.values()].filter(r=>r.group===g).map(r=>`<a href="#${r.id}" ${routeId()===r.id?'aria-current="page"':''}><span>${r.title}</span><span class="badge">${r.version}</span></a>`).join('')}`).join('')}<div class="divider"></div><p class="small muted">Wszystkie ekrany reagują na wybór motywu i szerokość okna. Ekrany natywne pokazują zakres poleceń; rzeczywiste ramki i uprawnienia dostarcza system.</p>`
}
function render(){
 const id=routeId(),r=routes.get(id)
 if(id==='focus-running'&&!state.running){state.running=true;state.end=Date.now()+state.remaining*1000}
 if(id==='focus-paused'&&state.running){state.remaining=Math.max(0,Math.ceil((state.end-Date.now())/1000));state.running=false}
 app.innerHTML=r.kind==='modal'?`${timer()}<div class="modal-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header">${nav(id==='settings'?'timer':'settings',icon('back'),'icon-btn')}<h1 id="dialog-title" tabindex="-1">${r.title}</h1>${nav('timer',icon('close'),'icon-btn')}</header><div class="dialog-body">${r.content()}</div><footer class="dialog-footer">${r.footer?r.footer():save()}</footer></section></div>`:r.content()
 // Keep the preview itself accessible: background content is inert while a dialog is open.
 if(r.kind==='modal')for(const n of [...app.children])if(!n.classList.contains('modal-backdrop'))n.inert=true
 document.querySelectorAll('a.icon-btn').forEach(a=>{if(!a.getAttribute('aria-label'))a.setAttribute('aria-label',a.hash==='#timer'?'Zamknij':a.hash==='#settings'?'Ustawienia':a.hash==='#session-edit'?'Edytuj sesję':'Otwórz '+(routes.get(a.hash.slice(1))?.title||'widok'))})
 const target=app.querySelector(r.kind==='modal'?'#dialog-title':'h1')
 if(target){target.tabIndex=-1;target.focus({preventScroll:true})}
 document.title=`${r.title} — Focus Flow · projekt`
 catalog()
 document.querySelector('#viewport').scrollTop=0
 window.scrollTo({top:0})
}
let toastTimer
function toast(message){const n=document.querySelector('#toast');n.textContent=message;n.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.hidden=true,3500)}
document.querySelector('#review-theme').innerHTML=themes.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')
function setTheme(theme){if(!themes.some(t=>t.id===theme))return;state.theme=theme;document.documentElement.dataset.theme=theme;document.querySelector('#review-theme').value=theme;document.querySelectorAll('input[name=theme]').forEach(n=>n.checked=n.value===theme)}
document.querySelector('#review-theme').addEventListener('change',e=>setTheme(e.target.value))
document.querySelector('#catalog-toggle').addEventListener('click',()=>{const n=document.querySelector('#catalog');n.hidden=!n.hidden;document.querySelector('#catalog-toggle').setAttribute('aria-expanded',String(!n.hidden))})
document.querySelector('#device-toggle').addEventListener('click',e=>{const mobile=document.body.classList.toggle('device-mobile');e.currentTarget.setAttribute('aria-pressed',String(mobile));e.currentTarget.textContent=mobile?'Widok komputera':'Widok telefonu'})
document.addEventListener('click',e=>{
 const target=e.target.closest('button,a');if(!target)return
 if(target.matches('.skip')){e.preventDefault();const main=app.querySelector('.dialog h1')||app.querySelector('#workspace');if(main){main.tabIndex=-1;main.focus()}return}
 if(target.closest('#catalog')&&target.matches('a')){document.querySelector('#catalog').hidden=true;document.querySelector('#catalog-toggle').setAttribute('aria-expanded','false')}
 if(target.matches('.switch')){target.setAttribute('aria-checked',String(target.getAttribute('aria-checked')!=='true'));return}
 if(target.closest('.pill-options')&&target.tagName==='BUTTON'){for(const n of target.parentElement.querySelectorAll('button'))n.setAttribute('aria-pressed',String(n===target));return}
 if(target.dataset.themeSelect){setTheme(target.dataset.themeSelect);location.hash='timer';return}
 const id=target.dataset.action;if(!id)return
 if(id==='delete-session'){state.deleted=true;location.hash='statistics';toast('Przykładowa sesja usunięta z podglądu.');return}
 if(id==='save-session'){const field=app.querySelector('.dialog input');if(field)sessions[0][1]=field.value;location.hash='statistics';toast('Zmiana zapisana w podglądzie.');return}
 if(id==='shortcut-edit'){location.hash='shortcut-conflict';return}
 if(id==='plant-select'){location.hash='garden';return}
 if(id==='more-sessions'){document.querySelector('#session-list').insertAdjacentHTML('beforeend',historyRows());target.disabled=true;toast('Wyświetlono kolejną przykładową stronę.');return}
 if(id==='sync-now'||id==='peer-sync'){toast('Symulacja: dane są aktualne. Nie wysłano żadnych danych.');return}
 if(id==='webhook-test'){location.hash='webhook-error';return}
 if(id.startsWith('tray-')){const destination={'tray-open':'timer','tray-pause':'focus-paused','tray-reset':'reset-confirm','tray-mini':'mini','tray-settings':'settings','tray-quit':'timer'}[id];location.hash=destination;return}
 if(id==='mini-pause'){target.textContent=target.textContent==='Wznów'?'Pauza':'Wznów';return}
 if(id==='add-step'){const n=document.createElement('label');n.className='field';n.innerHTML='<span class="field-label">Nowy krok</span><input class="input" placeholder="Najbliższe działanie">';target.before(n);n.querySelector('input').focus();return}
 const messages={'backup-preview':'Podgląd eksportu JSON. Nie odczytano danych aplikacji.','export-preview':'Podgląd pobierania. W prototypie nie powstaje plik z danymi.','voice-preview':'Podgląd komunikatu: sesja skupienia zakończona.','notification-test':'Przykład: sesja zakończona. Czas na przerwę.','add-sound':'Podgląd wyboru pliku. Żaden plik nie jest przesyłany.','remove-sound':'Przykładowy plik usunięty z podglądu.','shortcut-reset':'Przywrócono przykładowy zestaw skrótów.','copy-offer':'Podgląd kopiowania. Nie użyto schowka systemowego.','download-preview':'Oficjalne instalatory są w wydaniu 3.0 na GitHubie.'}
 toast(messages[id]||'Podgląd interakcji. Ustawienie pozostaje w tej sesji prototypu.')
})
document.addEventListener('input',e=>{
 if(e.target.matches('[data-task]'))state.task=e.target.value
 if(e.target.matches('input[type=range]'))e.target.closest('label').querySelector('output').textContent=e.target.value+e.target.dataset.unit
 if(e.target.matches('[data-history-search]'))document.querySelector('#session-list').innerHTML=historyRows(e.target.value)
 if(e.target.matches('[data-guide-search]')){let count=0;document.querySelectorAll('[data-guide]').forEach(n=>{n.hidden=!n.dataset.guide.includes(e.target.value.toLowerCase());if(!n.hidden)count++});document.querySelector('#guide-no-results').hidden=count>0}
})
document.addEventListener('change',e=>{if(e.target.name==='theme')setTheme(e.target.value);if(e.target.name==='language')state.language=e.target.value})
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){
  if(!document.querySelector('#catalog').hidden){document.querySelector('#catalog').hidden=true;document.querySelector('#catalog-toggle').setAttribute('aria-expanded','false');document.querySelector('#catalog-toggle').focus();return}
  if(routes.get(routeId()).kind==='modal')location.hash='timer'
 }
 if(e.key==='Tab'){
  const dialog=app.querySelector('.dialog');if(!dialog)return
  const list=[...dialog.querySelectorAll('a[href],button:not([disabled]),input,select,textarea,summary')].filter(n=>!n.closest('[hidden]'))
  const first=list[0],last=list.at(-1)
  if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.querySelector('h1'))){e.preventDefault();last.focus()}
  else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
 }
})
window.addEventListener('hashchange',render)
setInterval(()=>{
 if(!state.running)return
 state.remaining=Math.max(0,Math.ceil((state.end-Date.now())/1000))
 for(const n of app.querySelectorAll('[data-timer]'))n.textContent=formatTime(state.remaining)
 if(state.remaining===0){state.running=false;location.hash='complete'}
},1000)
// Read-only inspection surface for the design acceptance checks.
window.focusFlowDesign={screens:[...routes.values()].map(({id,title,group,kind,version})=>({id,title,group,kind,version})),themes:themes.map(({id,name})=>({id,name}))}
render()
